const input = $input.first().json;

const rawJid = input.body.data.key.remoteJid || '';
const senderNumber = rawJid.replace('@s.whatsapp.net', '').replace('@g.us', '');
const senderName = input.body.data.pushName || senderNumber;
const fromMe = input.body.data.key.fromMe === true;

const messageText = (
  input.body.data.message?.conversation ||
  input.body.data.message?.extendedTextMessage?.text ||
  input.body.data.message?.imageMessage?.caption ||
  input.body.data.message?.videoMessage?.caption ||
  input.body.data.message?.buttonsResponseMessage?.selectedButtonId ||
  input.body.data.message?.listResponseMessage?.singleSelectReply?.selectedRowId ||
  ''
).trim();

const normalized = messageText.toUpperCase().trim();

if (fromMe && (normalized === '++' || normalized === '--')) {
  return [{
    json: {
      _route: 'command',
      _command: normalized === '++' ? 'pause' : 'resume',
      senderNumber,
      senderName,
      messageText: normalized,
      fromMe: true
    }
  }];
}

if (fromMe) {
  return [{ json: { _route: 'ignore' } }];
}

return [{
  json: {
    _route: 'batch',
    senderNumber,
    senderName,
    messageText,
    fromMe: false
  }
}];

const staticData = $getWorkflowStaticData('global');
const input = $input.first().json;

const senderNumber = input.senderNumber;
const senderName = input.senderName;
const messageText = input.messageText;

const now = Date.now();
const windowMs = 3 * 60 * 1000;
const maxMessages = 30;

if (!staticData._batches) staticData._batches = {};
if (!staticData._manualModes) staticData._manualModes = {};

if (staticData._manualModes[senderNumber] === true) {
  return [{ json: { _action: 'ignore' } }];
}

if (!staticData._batches[senderNumber]) {
  staticData._batches[senderNumber] = {
    messages: [],
    startTime: now,
    lastMessageTime: now,
    senderName: senderName,
    processing: false,
    processingStartedAt: null
  };
}

const batch = staticData._batches[senderNumber];

const processingTimeoutMs = 2 * 60 * 1000;
if (batch.processing && batch.processingStartedAt && (now - batch.processingStartedAt > processingTimeoutMs)) {
  batch.processing = false;
  batch.processingStartedAt = null;
}

if (batch.processing) {
  if (batch.messages.length < maxMessages) {
    batch.messages.push({
      text: messageText,
      time: new Date(now).toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' })
    });
    batch.lastMessageTime = now;
    batch.senderName = senderName;
  }
  return [{ json: { _action: 'queued' } }];
}

if (batch.messages.length >= maxMessages) {
  return [{ json: { _action: 'spam_limit' } }];
}

batch.messages.push({
  text: messageText,
  time: new Date(now).toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' })
});
batch.lastMessageTime = now;
batch.senderName = senderName;

const idleTime = now - batch.lastMessageTime;
const batchReady = idleTime >= windowMs;

if (batchReady) {
  batch.processing = true;
  batch.processingStartedAt = now;
}

const allMessagesText = batch.messages
  .map((m, i) => `${i + 1}. [${m.time}] ${m.text}`)
  .join('\n');

return [{
  json: {
    _action: batchReady ? 'process' : 'wait',
    senderNumber,
    senderName: batch.senderName,
    messageCount: batch.messages.length,
    batchReady,
    allMessagesText
  }
}];

const input = $input.first().json;
const staticData = $getWorkflowStaticData('global');

if (!staticData._manualModes) staticData._manualModes = {};

const num = input.senderNumber;
const name = input.senderName;
const cmd = input._command;

if (cmd === 'pause') {
  staticData._manualModes[num] = true;
  if (staticData._batches) delete staticData._batches[num];
  return [{
    json: {
      bildirim: 'MANUEL MOD AKTIF\nMusteri: ' + name + ' (' + num + ')\nSistem bu musteriye otomatik cevap vermeyecek.\nCikmak icin -- yazin.',
      _skipCustomer: true
    }
  }];
} else {
  staticData._manualModes[num] = false;
  return [{
    json: {
      bildirim: 'OTOMATIK MOD AKTIF\nMusteri: ' + name + ' (' + num + ')\nSistem tekrar otomatik cevap verecek.',
      _skipCustomer: true
    }
  }];
}

const input = $input.first().json;
return [{
  json: {
    senderNumber: input.senderNumber,
    senderName: input.senderName,
    allMessagesText: input.allMessagesText,
    messageCount: input.messageCount,
    _prompt: 'Gonderen: ' + input.senderName + ' (' + input.senderNumber + ')\nMesaj sayisi: ' + input.messageCount + '\n\nMesajlar:\n' + input.allMessagesText
  }
}];

const aiOutput = $input.first().json?.output || '';

let senderNumber = '';
let senderName = '';
let allMessagesText = '';
try {
  const sc = $('Store Context').item.json;
  senderNumber = sc.senderNumber || '';
  senderName = sc.senderName || '';
  allMessagesText = sc.allMessagesText || '';
} catch (e) {}

let bildirim = '';
let cevap = 'Talebinizi aldik, en kisa surede donecegiz.';
let action = 'reply';
let intent = 'other';

try {
  const jsonMatch = aiOutput.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    bildirim = parsed.summary || parsed.bildirim || '';
    cevap = parsed.reply || parsed.cevap || cevap;
    action = parsed.action || 'reply';
    intent = parsed.intent || 'other';
  }
} catch (e) {}

if (!bildirim) {
  bildirim = senderName + ' ' + senderNumber + ' - ' + allMessagesText.substring(0, 80);
}

const intentTR = {
  product_compatibility: 'Uyumluluk',
  price_stock: 'Fiyat/Stok',
  order_status: 'Siparis',
  shipping: 'Kargo',
  return_complaint: 'Sikayet/Iade',
  wholesale: 'Toptan',
  greeting: 'Selamlama',
  unclear: 'Belirsiz',
  other: 'Diger'
};
const intentLabel = intentTR[intent] || intent;

const handoffTag = action === 'handoff' ? '\n\nINSANA AKTARILDI - Musteri insan temsilci bekliyor!' : '';

const detayliBildirim = 'YENI MESAJ - filtreto.com\n'
  + 'Gonderen: ' + senderName + '\n'
  + 'Numara: ' + senderNumber + '\n'
  + 'Konu: ' + intentLabel + '\n'
  + 'Ozet: ' + bildirim + handoffTag + '\n'
  + '\n'
  + 'Musteriye Gonderilen Yanit:\n'
  + cevap;

return [{
  json: {
    bildirim: detayliBildirim,
    cevap: action === 'handoff' ? '' : cevap,
    senderNumber,
    senderName,
    action
  }
}];

const input = $input.first().json;
const staticData = $getWorkflowStaticData('global');
const senderNumber = input.senderNumber;

if (staticData._batches && senderNumber) {
  delete staticData._batches[senderNumber];
}

if (!staticData._lastReply) staticData._lastReply = {};
if (senderNumber) {
  staticData._lastReply[senderNumber] = Date.now();
}

return [{ json: input }];

const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const windowMs = 3 * 60 * 1000;

if (!staticData._batches) staticData._batches = {};
if (!staticData._manualModes) staticData._manualModes = {};

const results = [];

for (const [number, batch] of Object.entries(staticData._batches)) {
  if (staticData._manualModes[number] === true) {
    delete staticData._batches[number];
    continue;
  }
  if (batch.processing) continue;
  const lastTime = batch.lastMessageTime || batch.startTime;
  const idleTime = now - lastTime;
  if (idleTime >= windowMs && batch.messages.length > 0) {
    batch.processing = true;
    batch.processingStartedAt = now;
    const allMessagesText = batch.messages.map((m, i) => `${i + 1}. [${m.time}] ${m.text}`).join('\n');
    results.push({
      json: {
        senderNumber: number,
        senderName: batch.senderName,
        messageCount: batch.messages.length,
        allMessagesText
      }
    });
  }
}

if (results.length === 0) {
  return [{ json: { senderNumber: '', messageCount: 0 } }];
}
return results;

const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const idleAlertMs = 10 * 60 * 1000;

if (!staticData._lastReply) staticData._lastReply = {};

const alerts = [];
for (const [number, lastReplyTime] of Object.entries(staticData._lastReply)) {
  if (now - lastReplyTime >= idleAlertMs) {
    alerts.push({
      json: {
        senderNumber: number,
        bildirim: 'Sessiz musteri - ' + number + ' - 10 dkdir cevap yazmiyor',
        _idleAlert: true
      }
    });
    delete staticData._lastReply[number];
  }
}

if (alerts.length === 0) {
  return [{ json: { _idleAlert: false } }];
}
return alerts;
